$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$providerJobsApi = Decode ""
$providerJobsPage = Decode ""

$apiPath = Join-Path $root "app\api\provider\jobs\route.ts"
$pagePath = Join-Path $root "app\provider\jobs\page.tsx"
$marketPath = Join-Path $root "app\api\market\requests\route.ts"

foreach ($path in @($pagePath, $marketPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "12.93 : fichier requis introuvable : $path"
    }
}

$migration83 = Get-ChildItem -LiteralPath (Join-Path $root "supabase\migrations") -File | Select-String -Pattern "KLYX_MULTI_SLOT_MARKET_12_83" -SimpleMatch -List

if (-not $migration83) {
    throw "12.93 : migration multi-slot 12.83 introuvable."
}

New-Item -ItemType Directory -Force -Path (Split-Path -Parent $apiPath) | Out-Null

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $pagePath -Destination ($pagePath + ".bak-12-93-" + $timestamp) -Force

if (Test-Path -LiteralPath $apiPath) {
    Copy-Item -LiteralPath $apiPath -Destination ($apiPath + ".bak-12-93-" + $timestamp) -Force
}

[System.IO.File]::WriteAllText($apiPath, $providerJobsApi, $utf8)
[System.IO.File]::WriteAllText($pagePath, $providerJobsPage, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 12.93 APPLIQUE"
Write-Host "======================================"
Write-Host "Provider Jobs multi-slot : OK"
Write-Host "Planning complet : OK"
Write-Host "Budget total : OK"
Write-Host "Couverture N/N : OK"
Write-Host "Couverture incomplete : MASQUEE"
Write-Host "1 offre pour tout le groupe : OK"
Write-Host "Missions simples : CONSERVEES"
Write-Host "Execution automatique : NON"
Write-Host "======================================"
Write-Host ""
